import {Vector3} from 'three';
export const poleControlDefaults=()=>({enabled:false,angle:0,parameter:'',stabilize:true,threshold:.01,maxGap:.25});
const fields=new Set(Object.keys(poleControlDefaults()));
export function validPoleControl(value){if(value===undefined)return true;if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).some(k=>!fields.has(k)))return false;const p={...poleControlDefaults(),...value};return typeof p.enabled==='boolean'&&Number.isFinite(p.angle)&&Math.abs(p.angle)<=360&&typeof p.parameter==='string'&&p.parameter.length<=160&&typeof p.stabilize==='boolean'&&Number.isFinite(p.threshold)&&p.threshold>=0&&p.threshold<=1&&Number.isFinite(p.maxGap)&&p.maxGap>0&&p.maxGap<=10;}
// Remember the unrotated component-space bend plane, so repeated evaluation of
// a fixed offset never accumulates twist. History is isolated per graph branch.
export class PoleControlIK{
 constructor(solver){this.solver=solver;this.p={...poleControlDefaults(),...solver.p.poleControl};this.states=new WeakMap();this.plane=new Vector3();this.debug=solver.debug.pole={active:false,angle:0,stabilized:false,plane:[0,0,0],resets:0};}
 apply(bend,axis,weak,frame={}){const s=this.solver,p=this.p,d=this.debug,{context=s.owner,epoch=0,time=s.owner.time||0}=frame,value=p.parameter?s.owner.parameters.get(p.parameter):0;d.active=Number.isFinite(value);d.stabilized=false;d.angle=0;if(!d.active){this.invalidate(context);return;}if(!Number.isFinite(time)||time<0||!Number.isSafeInteger(epoch)||epoch<0)throw Error('관절 회전 평가 시계를 확인하세요.');let state=this.states.get(context);if(state&&(time<state.time||time-state.time>p.maxGap||state.epoch!==epoch&&state.epoch!==epoch-1)){this.states.delete(context);state=null;d.resets++;}if(p.stabilize&&state&&weak){this.plane.copy(state.plane).addScaledVector(axis,-state.plane.dot(axis));if(this.plane.lengthSq()>1e-16){bend.copy(this.plane).normalize();d.stabilized=true;}}if(p.stabilize){if(!state){state={plane:new Vector3(),time,epoch};this.states.set(context,state);}state.plane.copy(bend);state.time=time;state.epoch=epoch;}else this.states.delete(context);d.angle=((p.angle%360)+(value%360))%360;bend.applyAxisAngle(axis,d.angle*Math.PI/180).normalize();bend.toArray(d.plane);}
 invalidate(context){this.states.delete(context);this.debug.active=false;this.debug.stabilized=false;this.debug.angle=0;}
 clear(){this.states=new WeakMap();this.solver=null;}
}
export const poleControlContract=Object.freeze({node:'twoBoneIK',property:'Optional poleControl; absent/disabled preserves legacy hint solver',fields:poleControlDefaults(),angle:'Authored angle plus optional Float parameter in degrees; reduced modulo360. Rotates the solved bend plane around root-to-target axis without moving the goal or changing authored segment lengths. Existing alpha/joint/twist/stretch constraints still apply.',stability:'If both incoming knee bend and weighted hint are weak relative to chain length*threshold, project the previous unrotated component-space bend plane onto the current target axis. No history or singular projection falls back to existing solver. Offset never accumulates.',lifetime:'Weak state per evaluated graph branch; clock rewind/evaluation gap/maxGap and zero effective alpha invalidate. Moving targets recompute axis; disable/dispose releases history. No state/scene scans for legacy nodes.',control:'Typed folded editor, Float reference validation/rename/Undo, existing graph patch and animGraphSetFloat/hb::AnimationGraph::SetFloat; detached schema and existing runtime status.',limits:'Bend-plane offset/singularity stability, not a full rig/pelvis/physical joint or predictive gait solver. Extreme target-axis changes or incompatible joint/twist limits can change the final knee and retain residual error.'});
